// Keeps the learner app's copy of the GLB viewer engine identical to the Admin's.
//
// The 3D viewer engine is ONE plain JavaScript file, admin-website/public/glb-viewer.v4.js, which the Admin loads as it is. The learner app runs the same text inside its WebView page, so
// it embeds it as a string in src/learning/glb-viewer-engine.ts. That file is GENERATED by this script and must never be edited by hand:
//
//   npm run sync:glb-engine      writes src/learning/glb-viewer-engine.ts from the Admin's file
//   npm run check:glb-engine     changes nothing; fails (exit 1) if the generated file is not exactly what the Admin's file would produce
//
// When the engine changes, raise the version in BOTH file names (the Admin's glb-viewer.vN.js, its loader in admin-website/lib/glb-viewer.ts, and SOURCE / VERSION below), then run the sync.
// The engine file contains no backslashes, backticks or dollar-brace sequences (checked below), which is what lets it be embedded as a template string without any escaping.
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const VERSION = 4;
const here = dirname(fileURLToPath(import.meta.url));
const SOURCE = join(here, '..', '..', 'admin-website', 'public', `glb-viewer.v${VERSION}.js`);
const TARGET = join(here, '..', 'src', 'learning', 'glb-viewer-engine.ts');

const LF = String.fromCharCode(10);
const CR = String.fromCharCode(13);
const BACKSLASH = String.fromCharCode(92);
const BACKTICK = String.fromCharCode(96);
const DOLLAR_BRACE = String.fromCharCode(36) + String.fromCharCode(123);

if (!existsSync(SOURCE)) {
  console.error(`The engine file was not found: ${SOURCE}`);
  process.exit(1);
}
const engine = readFileSync(SOURCE, 'utf8').split(CR + LF).join(LF);
for (const [what, text] of [['a backslash', BACKSLASH], ['a backtick', BACKTICK], ['a dollar-brace sequence', DOLLAR_BRACE]]) {
  if (engine.includes(text)) {
    console.error(`The engine file contains ${what}, so it cannot be embedded as it is. Remove it from ${SOURCE}.`);
    process.exit(1);
  }
}
if (!engine.includes(`var VERSION = ${VERSION};`)) {
  console.error(`The engine file does not declare version ${VERSION}. Keep the version in its name, in its text and in this script the same.`);
  process.exit(1);
}

const generated = [
  '/**',
  ` * GENERATED FILE. Do not edit it. It is the text of the GLB viewer engine (admin-website/public/glb-viewer.v${VERSION}.js, version ${VERSION}), embedded so the learner app's WebView page can run it`,
  ' * without loading anything from the internet, and it is produced by scripts/sync-glb-engine.mjs (npm run sync:glb-engine). The Admin and the app therefore always run the same engine.',
  ' * npm run check:glb-engine reports whether this file is up to date.',
  ' */',
  `export const GLB_VIEWER_ENGINE_VERSION = ${VERSION};`,
  '',
  `export const GLB_VIEWER_ENGINE = ${BACKTICK}${engine}${BACKTICK};`,
  '',
].join(LF);

if (process.argv.includes('--check')) {
  const current = existsSync(TARGET) ? readFileSync(TARGET, 'utf8').split(CR + LF).join(LF) : null;
  if (current === generated) {
    console.log(`In sync: the app embeds exactly glb-viewer.v${VERSION}.js.`);
  } else {
    console.error('NOT in sync: src/learning/glb-viewer-engine.ts differs from the Admin engine file. Run: npm run sync:glb-engine');
    process.exit(1);
  }
} else {
  writeFileSync(TARGET, generated, 'utf8');
  console.log(`Wrote ${TARGET} (${engine.length} characters of engine, version ${VERSION}).`);
}
